class Solution {
  public boolean[] transformStr(String s, String[] strs) {
    int n = s.length();
    int[] onesS = new int[n + 1];
    for (int i = 0; i < n; i++) onesS[i + 1] = onesS[i] + (s.charAt(i) == '1' ? 1 : 0);
    int total = onesS[n];
    boolean[] ans = new boolean[strs.length];
    for (int q = 0; q < strs.length; q++) {
      String t = strs[q];
      int fixedOnes = 0, wild = 0;
      for (int i = 0; i < n; i++) {
        if (t.charAt(i) == '1') fixedOnes++;
        else if (t.charAt(i) == '?') wild++;
      }
      int need = total - fixedOnes;
      if (need < 0 || need > wild) continue;
      // set the last `need` wildcards to one so that prefix counts stay as small as possible
      int wildcardsAfter = wild;
      int ones = 0;
      boolean ok = true;
      for (int i = 0; i < n && ok; i++) {
        char c = t.charAt(i);
        if (c == '1') ones++;
        else if (c == '?') {
          if (wildcardsAfter <= need) ones++;
          wildcardsAfter--;
        }
        if (ones > onesS[i + 1]) ok = false;
      }
      ans[q] = ok;
    }
    return ans;
  }
}
